#!/usr/bin/env node
// Keep one GitHub issue per day without erasing editorial notes outside the
// autogenerated section. All original content is retained during migration.
import { readFile, writeFile } from "node:fs/promises";
import assert from "node:assert/strict";

const START = "<!-- seed-news-review:auto-start -->";
const END = "<!-- seed-news-review:auto-end -->";
function merge(existing, report) {
  const block = START + "\n" + report.trim() + "\n" + END;
  if (!existing?.trim()) return block + "\n";
  const start = existing.indexOf(START), end = existing.indexOf(END);
  if (start >= 0 && end >= start) {
    if (existing.indexOf(START, start + START.length) !== -1 ||
        existing.indexOf(END, end + END.length) !== -1) throw Error("Duplicate managed region markers");
    return existing.slice(0, start) + block + existing.slice(end + END.length);
  }
  if (start >= 0 || end >= 0) throw Error("Incomplete managed-region markers; refusing to overwrite.");
  // Legacy issue contents may include editor-authored additions. Keep every
  // byte of that body in a collapsed archive instead of losing those notes.
  return block + "\n\n---\n\n<details>\n<summary>자동화 전환 전 보고서 원본 — 보존 기록</summary>\n\n" +
    existing.trim() + "\n\n</details>\n";
}
if (process.argv.includes("--self-test")) {
  const fresh = merge("", "# first");
  assert.ok(fresh.includes("# first"));
  assert.equal((merge(fresh + "\n\nManual note", "# revised").match(/Manual note/g) || []).length, 1);
  assert.ok(merge("EDITOR NOTE", "# new").includes("EDITOR NOTE"));
  assert.throws(() => merge(START + " incomplete", "# new"), /Incomplete/);
  console.log("Daily review merge self-test passed");
} else {
  if (process.argv.length !== 5) throw Error("Usage: node merge-news-tracker-report.mjs existing.md new.md output.md");
  const [oldPath, reportPath, outputPath] = process.argv.slice(2);
  const old = await readFile(oldPath, "utf8");
  const report = await readFile(reportPath, "utf8");
  await writeFile(outputPath, merge(old, report), "utf8");
  console.log("Daily review merged, preserving manual notes and prior archive.");
}